package com.clma.app.data.ai.tools

import androidx.annotation.StringRes
import com.clma.app.R

/**
 * Human-readable names for built-in tools, shown in the UI next to (never instead of) the raw
 * tool id: Settings → Tool approvals, the in-chat 本对话授权 sheet, approval cards and the
 * waiver / preset confirmations. Display-only — the model, the blacklist, the allow-list and
 * HARDLINE all keep working on raw ids.
 *
 * Every entry is an explicit `R.string` reference (no `getIdentifier`), so R8 resource
 * shrinking keeps them and a typo is a compile error. Strings live in
 * `values/strings_tool_names.xml` (short English defaults) and
 * `values-zh/strings_tool_names.xml` (Chinese). An id without an entry — a new tool, an
 * MCP tool — falls back to the raw id.
 */
object ToolDisplayNames {

    data class Res(@StringRes val name: Int, @StringRes val description: Int)

    /** Parts of a relayed MCP tool name `mcp__<slug8>_<server>__<tool>`, for display. */
    data class McpParts(val serverName: String, val toolName: String)

