    /** Every tool id that has a display name. */
    val knownIds: Set<String> get() = BY_ID.keys

    fun resFor(toolName: String): Res? = BY_ID[toolName]

    /**
     * Splits a relayed MCP tool name built by `buildMcpToolName` back into server and tool
     * names. Display-only best effort: the server part runs up to the first `__` after the
     * slug. Returns null for anything that is not `mcp__…`-shaped.
     */
    fun mcpParts(toolName: String): McpParts? {
        val prefix = ToolApprovalDefaults.MCP_TOOL_PREFIX
        if (!toolName.startsWith(prefix)) return null
        val rest = toolName.removePrefix(prefix)
        val slugEnd = rest.indexOf('_')
        if (slugEnd <= 0) return null
        val afterSlug = rest.substring(slugEnd + 1)
        val split = afterSlug.indexOf("__")
        if (split <= 0 || split + 2 >= afterSlug.length) return null
        return McpParts(serverName = afterSlug.substring(0, split), toolName = afterSlug.substring(split + 2))
    }
